function NODE_METHODS:GetChildren()
    local children = {}
    for _, child in pairs(self._children) do
        table.insert(children, child)
    end

    table.sort(children, function(a, b)
        return a.Name < b.Name
    end)

    return children
end

function NODE_METHODS:GetDescendants()
